transcript.raw_response:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper must not have a cart inside a single-file aisle bordered by shelves.",
    "abstraction": {
      "state_properties": {
        "opposingShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The rule is defined by aisle width and shelf adjacency rather than by any particular cell, so it can apply to any store with narrow shelf aisles."
  },
  {
    "id": "do_not_push_cart_into_single_file_aisle",
    "text": "A shopper must not move a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "cartEntryToSingleFileShelfAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntryToSingleFileShelfAisle"
    },
    "justification": "The prohibited transition is characterized by entering a geometrically narrow shelf aisle with a cart, not by entering any named coordinate."
  },
  {
    "id": "single_file_shelf_service_on_foot",
    "text": "Shelf interactions performed from a single-file shelf aisle must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The condition refers to interacting in any single-file shelf aisle, making it independent of where such aisles happen to be located."
  },
  {
    "id": "park_cart_only_in_open_passage",
    "text": "A shopper may only park or release a cart in an open non-shelf passage.",
    "abstraction": {
      "state_properties": {
        "openPassage": {
          "or": [
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "gt": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "openNonShelfPassage": {
          "and": [
            "openPassage",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "openNonShelfPassage"
          }
        ]
      }
    },
    "justification": "Parking suitability is expressed using clearance and shelf adjacency, so the norm transfers to other layouts with different cart-parking spots."
  },
  {
    "id": "reclaim_parked_cart",
    "text": "After parking a cart, a shopper is obliged to reclaim a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    },
    "justification": "The rule concerns the domain-level act of temporarily leaving and reclaiming a cart, regardless of the particular place where it happens."
  },
  {
    "id": "return_to_cart_after_single_file_shopping",
    "text": "After shopping on foot in a single-file shelf aisle, the shopper must return to and retrieve a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "onFootSingleFileShelfInteraction": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootSingleFileShelfInteraction",
      "discharge": "retrieveCart"
    },
    "justification": "The trigger is defined by the functional situation of shopping in a narrow shelf aisle on foot, not by the aisle's coordinates."
  },
  {
    "id": "use_cart_at_cart_accessible_shelf_front",
    "text": "When interacting with a shelf from a cart-accessible aisle, the shopper should have the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "cartAccessibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                {
                  "gt": [
                    "freeWidthH",
                    1
                  ]
                },
                {
                  "gt": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelfFront",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "Cart accessibility is inferred from local clearance and shelf adjacency, so the same distinction applies in stores with different shelf positions."
  },
  {
    "id": "leave_with_taken_cart",
    "text": "Once a shopper takes possession of a cart, they are obliged to leave the store while still having a cart.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "takeCart",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    },
    "justification": "This rule refers only to the shopping-domain relation between taking a cart and exiting with it, so it is not tied to any floor-plan geometry."
  }
]

